window.ScripturaLexicons.BDAG_PART_0259 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-01\" data-source=\"BDAG\" data-search=\"ὀρθρίζω verbo levantar-se muito cedo; procurar diligentemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀρθρίζω</td><td>verbo</td><td>levantar-se muito cedo; procurar diligentemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-02\" data-source=\"BDAG\" data-search=\"ὀρθρινός, ή, όν adjetivo muito cedo pela manhã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀρθρινός, ή, όν</td><td>adjetivo</td><td>muito cedo pela manhã</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-03\" data-source=\"BDAG\" data-search=\"ὄρθριος, ία, ιον adjetivo cedo pela manhã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄρθριος, ία, ιον</td><td>adjetivo</td><td>cedo pela manhã</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-04\" data-source=\"BDAG\" data-search=\"ὄρθρος, ου, ὁ substantivo masculino alvorada; começo da manhã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄρθρος, ου, ὁ</td><td>substantivo masculino</td><td>alvorada; começo da manhã</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-05\" data-source=\"BDAG\" data-search=\"ὀρθῶς advérbio corretamente; de modo justo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀρθῶς</td><td>advérbio</td><td>corretamente; de modo justo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-06\" data-source=\"BDAG\" data-search=\"ὁρίζω verbo delimitar; determinar; designar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁρίζω</td><td>verbo</td><td>delimitar; determinar; designar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-07\" data-source=\"BDAG\" data-search=\"ὅριον, ου, τό substantivo neutro fronteira; região; distrito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅριον, ου, τό</td><td>substantivo neutro</td><td>fronteira; região; distrito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-08\" data-source=\"BDAG\" data-search=\"ὁρισμός, οῦ, ὁ substantivo masculino trajetória determinada; percurso fixo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁρισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>trajetória determinada; percurso fixo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-09\" data-source=\"BDAG\" data-search=\"ὁρκίζω verbo conjurar; implorar sob juramento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁρκίζω</td><td>verbo</td><td>conjurar; implorar sob juramento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-10\" data-source=\"BDAG\" data-search=\"ὅρκιον, ου, τό substantivo neutro promessa solene; juramento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅρκιον, ου, τό</td><td>substantivo neutro</td><td>promessa solene; juramento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-11\" data-source=\"BDAG\" data-search=\"ὅρκος, ου, ὁ substantivo masculino juramento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅρκος, ου, ὁ</td><td>substantivo masculino</td><td>juramento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-12\" data-source=\"BDAG\" data-search=\"ὁρκωμοσία, ας, ἡ substantivo feminino prestação de juramento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁρκωμοσία, ας, ἡ</td><td>substantivo feminino</td><td>prestação de juramento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-13\" data-source=\"BDAG\" data-search=\"ὁρμάω verbo precipitar-se; correr impetuosamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁρμάω</td><td>verbo</td><td>precipitar-se; correr impetuosamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-14\" data-source=\"BDAG\" data-search=\"ὁρμή, ῆς, ἡ substantivo feminino impulso; inclinação; desejo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁρμή, ῆς, ἡ</td><td>substantivo feminino</td><td>impulso; inclinação; desejo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-15\" data-source=\"BDAG\" data-search=\"ὅρμημα, ατος, τό substantivo neutro investida; ímpeto violento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅρμημα, ατος, τό</td><td>substantivo neutro</td><td>investida; ímpeto violento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-16\" data-source=\"BDAG\" data-search=\"ὄρνεον, ου, τό substantivo neutro ave; pássaro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄρνεον, ου, τό</td><td>substantivo neutro</td><td>ave; pássaro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-17\" data-source=\"BDAG\" data-search=\"ὄρνιξ substantivo forma dórica de ave; variante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄρνιξ</td><td>substantivo</td><td>forma dórica de ave; variante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-18\" data-source=\"BDAG\" data-search=\"ὄρνις, ιθος, ὁ substantivo masculino/feminino ave; galo; galinha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄρνις, ιθος, ὁ</td><td>substantivo masculino/feminino</td><td>ave; galo; galinha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-19\" data-source=\"BDAG\" data-search=\"ὁροθεσία, ας, ἡ substantivo feminino fronteira delimitada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁροθεσία, ας, ἡ</td><td>substantivo feminino</td><td>fronteira delimitada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0259-20\" data-source=\"BDAG\" data-search=\"ὄρος, ους, τό substantivo neutro monte; montanha; colina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄρος, ους, τό</td><td>substantivo neutro</td><td>monte; montanha; colina</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0259-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀρθρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀρθρίζω</span> (assim na LXX e no NT; O. Amst 22, 8; PMilVogl II, 50, 13; Moeris p. 272 <span class=\"greek\">ὀρθρεύει</span> <span class=\"greek\">Ἀττικῶς</span>. <span class=\"greek\">ὀρθρίζει</span> <span class=\"greek\">Ἑλληνικῶς</span>), imperfeito <span class=\"greek\">ὤρθριζον</span>; futuro, 2ª pessoa singular, <span class=\"greek\">ὀρθρίσεις</span> e <span class=\"greek\">ὀρθριεῖς</span>, Judg. 9:33; 1º aoristo <span class=\"greek\">ὤρθρισα</span>, LXX, estar de pé ou levantar-se muito cedo pela manhã (ver os três artigos seguintes; Ex 24:4; 4 Km 6:15; SSol 7:13): <span class=\"greek\">ὁ</span> <span class=\"greek\">λαὸς</span> <span class=\"greek\">ὤρθριζεν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἱερῷ</span> <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">αὐτοῦ</span>, o povo costumava levantar-se muito cedo pela manhã para ir até ele no templo e ouvi-lo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:38</a> (<span class=\"greek\">ὀρ</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> também significa, em sentido geral, procurar alguém diligentemente: Job 8:5; Ps 77:34; Sir 4:12; 6:36; Wsd 6:14; Test Jos 3:6).—DELG s.v. <span class=\"greek\">ὄρθρος</span>. New Docs 1, 86 nº 43. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀρθρινός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀρθρινός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (ver o artigo precedente e os dois seguintes; substituto tardio de <span class=\"greek\">ὄρθριος</span> [Anecd. Gr. p. 54, 7; Lob., Phryn. p. 51], quase exclusivamente em poetas [Arat. 948; Posidippus Epigrammaticus, III a.C., em Athen. 13, 69 p. 596d; várias vezes na Anth. Pal.]; LXX), cedo pela manhã: <span class=\"greek\">γυναῖκες</span> … <span class=\"greek\">γενόμεναι</span> <span class=\"greek\">ὀρθριναὶ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μνημεῖον</span>, mulheres … que chegaram muito cedo ao sepulcro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:22</a>. <span class=\"greek\">τί</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">ὧδε</span> <span class=\"greek\">ἐλήλυθας</span>;, por que vieste aqui tão cedo?, Hs 5, 1, 1.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:16</a>, texto recebido (leitura erasmiana).—DELG s.v. <span class=\"greek\">ὄρθρος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄρθριος, ία, ιον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄρθριος</span>, <span class=\"greek\">ία</span>, <span class=\"greek\">ιον</span> (ver os dois artigos precedentes e o seguinte; Hom. Hymns e outros; papiros, LXX; Jos., Ant. 5, 330; 7, 195), cedo pela manhã, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:22</a>, variante de leitura (ver <span class=\"greek\">ὀρθρινός</span>).—DELG s.v. <span class=\"greek\">ὄρθρος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄρθρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄρθρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (ver os três artigos precedentes; Hes. e outros; papiros, LXX; En 100:2; Test Sol; Test Jos. 8:1; JosAs 11:1, códice A; ParJer 5:5; Joseph.), período relativamente cedo da manhã, alvorada, início da manhã: <span class=\"greek\">ὄρθρου</span> <span class=\"greek\">βαθέως</span>, muito cedo pela manhã, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:1</a> (ver <span class=\"greek\">βαθύς</span> 3b e cf. Heraclit. Sto. 16 p. 24, 16; 68 p. 88, 16; Polyaenus 4, 9, 1 <span class=\"greek\">ὄρθρος</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">βαθύς</span>). No mesmo sentido, <span class=\"greek\">φαίνοντος</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄρ</span>., já despontando a manhã, AcPl Ha 4, 3. <span class=\"greek\">ὄρθρου</span>, cedo pela manhã (Hes., Op. 577; Diod S 14, 104, 1; PFlor 305, 11; LXX; ParJer 5:5; Jos., Ant. 11, 37), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:2</a>; AcPl Ha 4, 6; 11, 11. <span class=\"greek\">ὄρθρου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κυριακῆς</span>, ao alvorecer do domingo, GPt 12:50. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὄρ</span>., por volta do amanhecer (Cass. Dio 76, 17; PFay 108, 10; Jos., Ant. 8, 382), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:21</a>.—B. 993. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀρθῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀρθῶς</span>, advérbio de <span class=\"greek\">ὀρθός</span> (Hes., Aeschyl., Hdt. e posteriores; inscrições, papiros, LXX; Test Sol 24:5 Q; Test12Patr; ParJer 7:11; GrBar 4:10; EpArist, Philo; Jos., Ant. 1, 251; Just.; Tat. 18, 2; Ath. 7, 1 e R. 21 p. 74, 26), relativo a agir em conformidade com uma norma ou padrão, corretamente, de modo justo: <span class=\"greek\">λαλεῖν</span>, falar corretamente, isto é, normalmente («de maneira adequada», TBaird, ET 92, ’81, 337f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:35</a>. <span class=\"greek\">ὀρ</span>. <span class=\"greek\">προσφέρειν</span>, <span class=\"greek\">διαιρεῖν</span>, oferecer corretamente, dividir corretamente, 1 Cl 4:4 (conforme Gen 4:7; ver <span class=\"greek\">διαιρέω</span>). <span class=\"greek\">δουλεύειν</span> <span class=\"greek\">αὐτῷ</span> (= <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>) <span class=\"greek\">ὀρ</span>., servir a Deus corretamente = <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημα</span> <span class=\"greek\">αὐτοῦ</span>, Hm 12, 6, 2. <span class=\"greek\">τελεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διακονίαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ὀρ</span>., realizar corretamente o serviço do Senhor, Hs 2:7; <span class=\"greek\">ἐργάζεσθαι</span> <span class=\"greek\">ὀρ</span>., agir corretamente, 8, 11, 4 (cf. <span class=\"greek\">ὀρ</span>. <span class=\"greek\">ποιεῖν</span>: SIG 116, 10; 780, 37; PEleph 9, 3; 1 Macc 11:43; Just., D. 5, 2; 67, 4; <span class=\"greek\">ὀρ</span>. <span class=\"greek\">πράσσειν</span>: Jos., Vi. 298; Just., A I, 4, 8). <span class=\"greek\">ὀρ</span>. <span class=\"greek\">κρίνειν</span>, julgar, decidir corretamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:43</a> (cf. Wsd 6:4; Ps.-Clem., Hom. 10, 9.—Diod S 18, 56, 3 <span class=\"greek\">ὀρθῶς</span> <span class=\"greek\">γινώσκειν</span> = pensar corretamente). <span class=\"greek\">ὀρ</span>. <span class=\"greek\">ἀποκρίνεσθαι</span>, responder corretamente (Herm. Wr. 13, 3; Just., D. 3, 6; cf. <span class=\"greek\">ὀρ</span>. <span class=\"greek\">ἐρωτᾷς</span>, GrBar 4:10), 10:28. <span class=\"greek\">ὀρ</span>. <span class=\"greek\">λέγειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">διδάσκειν</span>, falar e ensinar corretamente, 20:21 (cf. Aristoxenus, Fgm. 33 p. 18, 2 <span class=\"greek\">ὀρθῶς</span> <span class=\"greek\">λέγοντες</span>; Alex. Aphr., An. II/1 p. 20, 29 <span class=\"greek\">ὀρθῶς</span> <span class=\"greek\">λέγειν</span> = ensinar corretamente. Sobre Cercidas [III a.C.] em Diehl 3, Fgm. 11a, 4 [=Coll. Alex. p. 213 nº 16] <span class=\"greek\">ὀρθῶς</span> <span class=\"greek\">λέγει</span> <span class=\"greek\">που</span> <span class=\"greek\">Κερκίδας</span>; Dt 5:28). <span class=\"greek\">ὀρ</span>. <span class=\"greek\">διδάσκεσθαι</span>, ser corretamente instruído, Dg 11:2. <span class=\"greek\">ἀγαπᾶν</span> <span class=\"greek\">ὀρ</span>., amar (alguém) corretamente, 12:1. <span class=\"greek\">ὀρ</span>. <span class=\"greek\">ἀπέχεσθαί</span> <span class=\"greek\">τινος</span>, ter razão em abster-se de algo, 4:6.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁρίζω</span> (<span class=\"greek\">ὅρος</span>), futuro, 3ª pessoa singular, <span class=\"greek\">ὁριεῖ</span>, LXX; 1º aoristo <span class=\"greek\">ὥρισα</span>; perfeito, 3ª pessoa plural, <span class=\"greek\">ὁρίκασιν</span> (Tat. 17, 3). Passiva: 1º aoristo, 3ª pessoa singular, <span class=\"greek\">ὡρίσθη</span> (Just., A I, 44, 12); particípio <span class=\"greek\">ὁρισθείς</span>; particípio perfeito <span class=\"greek\">ὡρισμένος</span> (Aeschyl., Hdt. e posteriores). ① Do sentido básico «separar entidades e assim estabelecer uma fronteira» deriva o sentido de «definir ideias ou conceitos»: estabelecer limites, definir, explicar (X. e outros [como Ath. 6, 1], nas vozes ativa e média); <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, dar explicação acerca de algo, 12:1. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σταυρὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">ὥρισεν</span>, definiu a água e a cruz conjuntamente (isto é, na seção sobre a árvore junto às correntes de água, Ps 1:3), 11:8. Semelhantemente. ② Tomar uma decisão ou determinação acerca de uma entidade, determinar, designar, fixar, estabelecer. ⓐ Sobre coisas. <span class=\"greek\">α</span>. Expressas pelo acusativo: <span class=\"greek\">προφήτης</span> <span class=\"greek\">ὁρίζων</span> <span class=\"greek\">τράπεζαν</span>, profeta que determina uma refeição (ver <span class=\"greek\">τράπεζα</span> 2), D 11:9 (com duplo acusativo: <span class=\"greek\">Πυθαγόρας</span> … <span class=\"greek\">ἔσχατον</span> <span class=\"greek\">ὁρίζει</span> <span class=\"greek\">φύσιν</span>, Theoph. Ant. 3, 7 [p. 216, 12]).—Sobre o tempo (Pla., Leg. 9 p. 864e; Demosth. 36, 26 <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">χρόνον</span> <span class=\"greek\">ὥρισεν</span>; Epict., Ench. 51, 1; PFlor 61, 45 [85 d.C.]; Jos., C. Ap. 1, 230; Just., D. 102, 4 <span class=\"greek\">χρόνους</span>; mais frequentemente na passiva, ver adiante): <span class=\"greek\">ἡμέραν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:7</a>. <span class=\"greek\">ὁρ</span>. <span class=\"greek\">προστεταγμένους</span> <span class=\"greek\">καιρούς</span>, fixar tempos determinados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:26</a>.—<span class=\"greek\">μηδὲν</span> <span class=\"greek\">ὁρίζοντες</span> <span class=\"greek\">μηδὲ</span> <span class=\"greek\">νομοθετοῦντες</span>, sem estabelecer regras nem ordenanças, GMary 463, 29.—Passiva (SIG 495, 171; PFay 11, 16 [cerca de 115 a.C.]; PAmh 50, 15; PTebt 327, 12 e outros): <span class=\"greek\">ὡρισμένοι</span> <span class=\"greek\">καιροί</span> (Diod S 1, 41, 7; cf. 16, 29, 2; Jos., Ant. 6, 78), tempos determinados, 1 Cl 40:2. <span class=\"greek\">ὡρισμένης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ταύτης</span>, depois de fixado esse dia, Hv 2, 2, 5 (Diod S 2, 59, 5; 20, 110, 1 <span class=\"greek\">ὡρισμένη</span> <span class=\"greek\">ἡμέρα</span>; Herodian 1, 10, 5 <span class=\"greek\">ὡρισμένης</span> <span class=\"greek\">ἡμέρας</span>; Pollux 1, 67).—<span class=\"greek\">ὁ</span> <span class=\"greek\">ὡρισμένος</span> <span class=\"greek\">τόπος</span>, lugar determinado, 19:1 (cf. Iren. 5, 31, 2 [Harv. II 412, 1]). <span class=\"greek\">οἱ</span> <span class=\"greek\">ὡρισμένοι</span> <span class=\"greek\">νόμοι</span>, leis estabelecidas, Dg 5:10. <span class=\"greek\">ὁ</span> <span class=\"greek\">ὡρισμένος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λειτουργίας</span> <span class=\"greek\">κανών</span>, limites estabelecidos do ministério (de alguém), 1 Cl 41:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὡρισμένη</span> <span class=\"greek\">βουλή</span>, plano determinado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:23</a>.—Substantivado (cf. SIG 905, 14 <span class=\"greek\">τῶν</span> <span class=\"greek\">ὁρισθέντων</span> <span class=\"greek\">ἄγνοια</span>): <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὡρισμένον</span>, de acordo com o decreto (divino), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:22</a>. <span class=\"greek\">β</span>. Com infinitivo (Appian, Bell. Civ. 5, 3 §12 <span class=\"greek\">ἀντιδοῦναι</span> = retribuir; ApcMos 28 <span class=\"greek\">φυλάττειν</span>; B-D-F § 392, 1a): <span class=\"greek\">ὥρισαν</span> … <span class=\"greek\">πέμψαι</span>, determinaram … enviar (talvez «separaram para», assim Field, Notes 119f e TGillieson, ET 56, ’44/45, 110), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:29</a>; com pergunta indireta, 1 Cl 40:3. ⓑ Sobre pessoas, designar, nomear, declarar: Deus julga o mundo <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνδρὶ</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ὥρισεν</span>, por meio de um homem que designou, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:31</a>. Passiva: <span class=\"greek\">ὁ</span> <span class=\"greek\">ὡρισμένος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">κριτής</span>, aquele designado por Deus como juiz, 10:42. Sobre dirigentes ou supervisores eclesiásticos: <span class=\"greek\">οἱ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πέρατα</span> <span class=\"greek\">ὁρισθέντες</span>, os que foram designados em terras distantes, IEph 3:2. Com duplo acusativo, declarar alguém como algo (Meleag. em Anth. Pal. 12, 158, 7 <span class=\"greek\">σὲ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ὥρισε</span> <span class=\"greek\">δαίμων</span>); passiva: <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὁρισθέντος</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δυνάμει</span>, aquele que foi declarado Filho de Deus em poder, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:4</a>.—DELG s.v. <span class=\"greek\">ὅρος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ὅρος</span>; Soph., Thu. e outros; inscrições, papiros, LXX; TestJud, JosAs), marcador que separa duas áreas, fronteira, limite; principalmente, e exclusivamente em nossa literatura, no plural, fronteiras = região, distrito (Gen 10:19; Ex 10:4 e outras passagens da LXX; TestJud 2:6; JosAs), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:34</a>; 15:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.50\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:50</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁρ</span>. <span class=\"greek\">Ζαβουλὼν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Νεφθαλίμ</span>, na região de Zebulom e Naftali, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:13</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅρ</span>. <span class=\"greek\">Μαγαδάν</span>, as regiões de Magadã, 15:39. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰουδαίας</span>, as regiões da Judeia, 19:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:1</a> (Jos., C. Ap. 1, 251 <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Συρίας</span>). Sobre a região ao redor de uma cidade (Jos., Ant. 6, 191): <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅρ</span>. <span class=\"greek\">Τύρου</span> (<span class=\"greek\">καὶ</span> <span class=\"greek\">Σιδῶνος</span>), as regiões de Tiro (e de Sidom), 7:24 (variante de leitura <span class=\"greek\">μεθόρια</span>); cf. versículo 31a. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὁρ</span>. <span class=\"greek\">ἐκείνων</span>, daquela região, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:22</a>. <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὁρ</span>. <span class=\"greek\">Δεκαπόλεως</span>, através da região de Decápolis, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:31b</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">Βηθλέεμ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὁρ</span>. <span class=\"greek\">αὐτῆς</span>, em Belém e em toda a região ao seu redor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:16</a>. <span class=\"greek\">ἔστησεν</span> <span class=\"greek\">ὅρ</span>. <span class=\"greek\">ἐθνῶν</span>, estabeleceu os territórios (talvez as fronteiras) das nações, 1 Cl 29:2 (Dt 32:8).—O sentido de «fronteiras» é certo em <span class=\"greek\">ὅρια</span> <span class=\"greek\">πατέρων</span> <span class=\"greek\">παρορίζειν</span>, ultrapassar as fronteiras estabelecidas pelos pais, Dg 11:5, variante de leitura (mas no texto de Wengst).—B. 1311f. DELG s.v. <span class=\"greek\">ὅρος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁρισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁρισμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ὁρίζω</span>; Hippocr. e outros; IMakedD 592, 2 [XIII d.C.] «ordenança»; papiros, LXX; Philo, Leg. All. 2, 63), literalmente «demarcação por fronteiras», depois, percurso fixo, trajetória determinada. Corpos celestes <span class=\"greek\">ἐξελίσσουσιν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐπιτεταγμένους</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὁρ</span>., percorrem seus cursos predeterminados, 1 Cl 20:3.—DELG s.v. <span class=\"greek\">ὅρος</span>. M-M s.v. <span class=\"greek\">ὁρίζω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁρκίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁρκίζω</span> (<span class=\"greek\">ὅρκος</span>), futuro, 3ª pessoa singular, <span class=\"greek\">ὁρκιεῖ</span>; 1º aoristo <span class=\"greek\">ὥρκισα</span>; particípio aoristo passivo <span class=\"greek\">ὁρκισθείς</span>: todas essas formas na LXX (no sentido de «fazer alguém prestar juramento», X. e outros; inscrições, papiros, LXX, TestSol; ParJer 8:10; Jos., Ant. 18, 124; Hippol.), dirigir uma ordem a alguém sob juramento, conjurar, implorar (assim nos papiros; Jos., Vi. 258; LXX); <span class=\"greek\">τινὰ</span> <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, conjurar alguém por alguém (PGM 3, 36f; 4, 289; 7, 242 <span class=\"greek\">ὁρκίζω</span> <span class=\"greek\">σε</span>, <span class=\"greek\">δαίμων</span>, <span class=\"greek\">κατὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀνομάτων</span> <span class=\"greek\">σου</span>; 3 Km 2:42; 2 Ch 36:13.—IDefixAudollent p. 473ff; ParJer 8:10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:63</a>, variante de leitura. <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ὁρ</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, com <span class=\"greek\">ἵνα</span> em seguida, Hs 9, 10, 5. Também com duplo acusativo (Orphica: Fgm., K. p. 313 nº 299 <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">ὁρκίζω</span> <span class=\"greek\">σε</span>; tabuleta de chumbo de Hadrumeto em Dssm., B 28 [BS 274] <span class=\"greek\">ὁρκίζω</span> <span class=\"greek\">σε</span>, <span class=\"greek\">δαιμόνιον</span> <span class=\"greek\">πνεῦμα</span>, <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Αβρααν</span> <span class=\"greek\">κτλ</span>.; PGM 4, 3045; B-D-F § 149; Rob. 483f): <span class=\"greek\">ὁρ</span>. <span class=\"greek\">σε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, eu te conjuro por Deus, com <span class=\"greek\">μή</span> em seguida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:7</a>. <span class=\"greek\">ὁρ</span>. <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:13</a> (cf. PGM 4, 3019 <span class=\"greek\">ὁρκίζω</span> <span class=\"greek\">σε</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἑβραίων</span> <span class=\"greek\">Ἰησοῦ</span>). Com duplo acusativo e, em seguida, acusativo e infinitivo (B-D-F § 392, 1d; Rob. 1085), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:27</a>, variante de leitura.—B. 1437. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅρκιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅρκιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (= <span class=\"greek\">ὅρκος</span>; Hom. e posteriores; OGI 453, 25 [39/35 a.C.]; SIG 581, 91 e outros; Philo, Conf. Lingu. 43; SibOr 3, 654), promessa solene, juramento, voto, compromisso: <span class=\"greek\">ὅρκια</span> <span class=\"greek\">πίστεως</span>, compromissos de fé, Dg 11:5 (conjectura de Lachmann; ver aparato de Bihlmeyer).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅρκος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅρκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. e posteriores), juramento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:16</a>. <span class=\"greek\">ὅρκον</span> <span class=\"greek\">ὀμνύειν</span>, prestar juramento (Hyperid. 5, 1; Lucian, Dial. Mer. 2, 1; PHal 1, 226; 230 <span class=\"greek\">ὀμόσας</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὅρκον</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:12</a> (mandamentos délficos: SIG 1268 I, 8 [III a.C.] <span class=\"greek\">ὅρκῳ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">χρῶ</span>). <span class=\"greek\">ὅρκῳ</span> <span class=\"greek\">ὀμνύειν</span> <span class=\"greek\">τινί</span>, jurar a alguém mediante juramento (TestJud 22:3; ApcMos 19), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:30</a>. <span class=\"greek\">ὅρ</span>. <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ὤμοσεν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">Ἀβραάμ</span>, juramento que fez a Abraão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.73\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:73</a> (cf. OGI 266, 19 <span class=\"greek\">ὅρκος</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ὤμοσεν</span> <span class=\"greek\">Παράνομος</span>; para o infinitivo seguinte com artigo, cf. Pel.-Leg. p. 13, 9 <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅρκῳ</span> <span class=\"greek\">εἶχεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γεύσασθαί</span> <span class=\"greek\">τι</span>). <span class=\"greek\">ὅρ</span>. <span class=\"greek\">ψευδής</span>, juramento falso (Theoph. Ant. 2, 34 [p. 186, 10]), 2:8 (Zech 8:17). <span class=\"greek\">ἀποδιδόναι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὅρκους</span>, cumprir os juramentos feitos ao Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:33</a> (ver <span class=\"greek\">ἀποδίδωμι</span> 2c. Mas <span class=\"greek\">ἀποδοῦναι</span> <span class=\"greek\">τινι</span> <span class=\"greek\">ὅρκον</span> também significa «prestar juramento»: Demosth. 19, 318; Aeschin. 3, 74; SIG 150, 15). <span class=\"greek\">μεσιτεύειν</span> <span class=\"greek\">ὅρκῳ</span>, garantir mediante juramento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:17</a>. <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ὅρκου</span>, mediante juramento (PRev 42, 17 [258 a.C.] <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ὅρκου</span>; Lev 5:4; Num 30:11; Cornutus 24 p. 46, 8 <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ὅρκων</span>; Just., D. 33, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:7</a>; 26:72; 1 Cl 8:2.—Plural <span class=\"greek\">ὅρκη</span>, mesmo quando há basicamente um único juramento envolvido (cf. X., Hell. 5, 4, 54; Diod S 4, 46, 4; 17, 84, 1; Polyaenus 2, 19; Athen. 13, 557a; 2 Macc 4:34; 7:24; 14:32; EpArist 126; Jos., Ant. 3, 272; 7, 294): <span class=\"greek\">διὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὅρκους</span>, por causa de seus juramentos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:26</a>.—ESanders, Jewish Law fr. Jesus to the Mishnah ’90, 51–57, 337f (nota). Bibliografia sobre <span class=\"greek\">ὀμνύω</span>: Kl. Pauly II, 209f.—B. 1438. DELG s.v. <span class=\"greek\">ὅρκος</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁρκωμοσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁρκωμοσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (composto de <span class=\"greek\">ὅρκον</span> <span class=\"greek\">ὀμόσαι</span> [<span class=\"greek\">ὄμνυμι</span>], «prestar juramento»), forma dórica.—O neutro <span class=\"greek\">ὁρκωμόσιον</span>, SIG 1007, 29 [130–100 a.C.], e seu plural, OGI 229, 82 [III a.C.]. Pollux 1, 38; 1 Esdr 8:90; Ezk 17:18f; Jos., Ant. 16, 163.—B-D-F § 2; 119, 3; ver Mlt-H. 338f; EFraenkel, Geschichte der griech. Nomina agentis auf- <span class=\"greek\">τήρ</span>,- <span class=\"greek\">τωρ</span>,- <span class=\"greek\">της</span> I 1910, 200), o processo de prestar juramento, ato de jurar, juramento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:20f</a> (não há prestação de juramento envolvida), 28 (há prestação de juramento envolvida).—DELG s.v. <span class=\"greek\">ὅρκος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁρμάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁρμάω</span> (<span class=\"greek\">ὁρμή</span>), 1º aoristo <span class=\"greek\">ὥρμησα</span>; mais-que-perfeito médio <span class=\"greek\">ὥρμηντο</span> (Just., A I, 29, 4), em nossa literatura usado somente de forma intransitiva (assim Hom. e posteriores; SIG 709, 19 [cerca de 107 a.C.]; PStras 100, 17 [II a.C.]; PTebt 48, 24; LXX, Test12Patr, Philo, Joseph., Just.; Ath. 2, 2 e R. 1 p. 48, 5), realizar movimento rápido de um lugar para outro, precipitar-se, correr impetuosamente: <span class=\"greek\">ὁρ</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κρημνοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span>, precipitar-se pela encosta até o lago, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:13</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:33</a> (cf. POxy 901, 6, acerca de dois porcos: <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁρμὴν</span> <span class=\"greek\">ποιούμενοι</span>). De uma multidão: <span class=\"greek\">ὥρμησαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέατρον</span>, precipitaram-se para dentro do teatro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:29</a> (cf. Jos., Ant. 11, 147). <span class=\"greek\">ὁρ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, precipitar-se contra alguém, atacá-lo (X., An. 4, 3, 31; Alciphron 3, 7, 3; 3, 18, 2; 2 Macc 12:32; Jos., Ant. 12, 270, Vi. 245; TestJud 7:5), 7:57.—Frisk s.v. <span class=\"greek\">ὁρμή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁρμή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁρμή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> («movimento rápido para a frente» [ver <span class=\"greek\">ὁρμάω</span>], Hom. e outros; SIG 700, 23 [117 a.C.]), em nossa literatura, estado psicológico de forte tendência, impulso, inclinação, desejo (assim Hom. e outros; PGrenf II 78, 15; 3 Macc 1:16); do piloto de um navio: <span class=\"greek\">ὅπου</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">εὐθύνοντος</span> <span class=\"greek\">βούλεται</span>, onde quer que o impulso do timoneiro o conduza, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:4</a>. <span class=\"greek\">καταδιαιρεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ὁρμάς</span>, estabelecer distinção entre certas coisas segundo suas próprias inclinações, Dg 4:5. <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ὁρ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐθνῶν</span>, houve uma tentativa por parte dos gentios, seguido de infinitivo aoristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:5</a> (cf. Jos., Ant. 9, 161 <span class=\"greek\">ὁρμὴ</span> <span class=\"greek\">ἀνακαινίσαι</span> e 15, 52 <span class=\"greek\">ὁρ</span>. <span class=\"greek\">ἐγένετο</span>).—Frisk. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅρμημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅρμημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ὁρμάω</span>; Hom. e outros; Plut., LXX), precipitação violenta, investida: <span class=\"greek\">ὁρμήματι</span> <span class=\"greek\">βληθήσεται</span> <span class=\"greek\">Βαβυλών</span>, Babilônia será lançada abaixo com violência, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:21</a> (Charles, Rv ad loc., «indignação»; cf. Hos 5:10 e ver <span class=\"greek\">ὁρμή</span>).—Frisk s.v. <span class=\"greek\">ὁρμή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄρνεον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄρνεον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (forma diminutiva = <span class=\"greek\">ὄρνις</span>; Hom. e outros; IG IV 2 /1, 93, 17 [III/IV d.C.]; PPetr III, 71 [III a.C.]; PRyl 98[a], 9; PLond III, 1259, 16 p. 240 [IV d.C.]; LXX; TestSol; JosAs 11:1, códice A; GrBar, Philo; Jos., Ant. 1, 184; 3, 25; 18, 195), ave, pássaro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:17</a>, 21. <span class=\"greek\">πᾶν</span> <span class=\"greek\">ὄρ</span>. <span class=\"greek\">ἀκάθαρτον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μεμισημένον</span>, toda ave impura e detestada (por motivos cultuais; por exemplo, coruja, garça, pelicano, corujão), 18:2 (cf. Dt 14:11 <span class=\"greek\">πᾶν</span> <span class=\"greek\">ὄρνεον</span> <span class=\"greek\">καθαρόν</span>). Do pássaro fênix, 1 Cl 25:2; 26:1. Plural, acerca de várias aves impuras (cf. Dt 14:11ff), 10:4. Com <span class=\"greek\">κτῆνος</span>, Hs 9, 1, 8.—DELG s.v. <span class=\"greek\">ὄρνις</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄρνιξ</h1><div class=\"entry-meta\"><span>substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄρνιξ</span> (assim como nominativo, Athen. 9, 374d; Herodian Gramm. I p. 44, 7 L.; PCairZen 375, 1. Dativo plural <span class=\"greek\">ὄρνιξι</span> também em PLond I, 131 anverso, 125 p. 173; 202 p. 175 e outros [78/79 d.C.]; ver Mayser 531.—Sobre essa forma dórica, ver Kühner-Bl. I 510; Thumb 90f; APF 4, 1908, 490; Crönert 174, 5; FRobert, Les noms des Oiseaux en grec ancien, dissertação Basel 1911, 17; B-D-F § 47, 4; DELG s.v. <span class=\"greek\">ὄρνις</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:34</a>, variante de leitura em lugar da forma ática <span class=\"greek\">ὄρνις</span>, ver esse artigo. W-S. §9, 10; Mlt-H. 130f; 133.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄρνις, ιθος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino/feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄρνις</span>, <span class=\"greek\">ιθος</span>, <span class=\"greek\">ὁ</span> e <span class=\"greek\">ἡ</span> (Hom. e posteriores; papiros; 3 Km 5:3 [Swete 4:23; ver Thackeray p. 152f]; SibOr 2, 208 [<span class=\"greek\">ὄρνεις</span>]; Philo; Jos., Bell. 2, 289 [<span class=\"greek\">ὄρνεις</span>], C. Ap. I, 203f [<span class=\"greek\">τὸν</span> <span class=\"greek\">ὄρνιθα</span>], Ant. 18, 185 [<span class=\"greek\">τὸν</span> <span class=\"greek\">ὄρνιν</span>]; Tat.), em geral «ave», especificamente «galo» ou «galinha» (Aeschyl.; X., An. 4, 5, 25; Polyb. 12, 26, 1 e outros; TAM II/1, 245, 8; papiros); no NT, apenas no feminino, galinha. O comportamento da ave-mãe, ou especificamente da galinha, como símbolo de cuidado protetor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:34</a>.—D’Arcy Thompson, A Glossary of Greek Birds ’36; AParmelee, All the Birds of the Bible ’69. B. 175. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁροθεσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁροθεσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὅρος</span>, <span class=\"greek\">τίθημι</span>; IPriene 42 II, 8 [133 a.C.] <span class=\"greek\">δικαίαν</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἔκριναν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ῥωδίων</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁροθεσίαν</span>; BGU 889, 17 [II d.C.].—B-D-F § 119, 3; Mlt-H. 340), fronteira estabelecida, limite fixo: <span class=\"greek\">ὁρίσας</span> … <span class=\"greek\">τὰς</span> <span class=\"greek\">ὁροθεσίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κατοικίας</span> <span class=\"greek\">αὐτῶν</span> (= <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπων</span>), (Deus) determinou as fronteiras da habitação deles, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:26</a> (ver HCadbury, JBL 44, 1925, 219–21, «fixou o período de residência».—MDibelius, SBHeidAk 1938/39 2. Abh, p, 7f; 15: «áreas delimitadas a colonizar»; WEltester, RBultmann Festschr., ’54, 209ff).—DELG s.v. <span class=\"greek\">ὅρος</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0259-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄρος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄρος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom. e posteriores), plural <span class=\"greek\">τὰ</span> <span class=\"greek\">ὄρη</span>; genitivo não contraído <span class=\"greek\">ὀρέων</span> (já em X., An. 1, 2, 21 [Kühner-Bl. I 432]; SIG 646, 18 [170 a.C.]; LXX [Thackeray 151; Helbing 41f]; EpArist 119. Joseph. prefere <span class=\"greek\">ὀρῶν</span>.—Schweizer 153; B-D-F § 48; Mlt-H. 139), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:15</a>; 1 Cl; Hermas (Reinhold 52); elevação relativamente grande do terreno, mais alta que um <span class=\"greek\">βοῦνος</span> («elevação menor, colina»), montanha, monte, colina (no vocabulário inglês, o que é considerado «montanha» em determinada região pode ser chamado «colina» por alguém oriundo de região com cadeias montanhosas extremamente altas; flexibilidade semelhante caracteriza o emprego de <span class=\"greek\">ὄρος</span>, e as traduções inglesas sugerem apenas uma perspectiva comparativa; em comparação com o monte Everest [8848 metros] ou o monte McKinley [6194 metros], qualquer montanha da Palestina é mera colina); com <span class=\"greek\">βουνός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:5</a> (Is 40:4); 23:30 (Hos 10:8). Com <span class=\"greek\">πέτρα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:16</a>; cf. versículo 15. Com <span class=\"greek\">πεδίον</span> (SIG 888, 120f), Hs 8, 1, 1; 8, 3, 2. Com <span class=\"greek\">νῆσος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:14</a>; 16:20. Como cenário de acontecimentos destacados e lugares de solidão (PTebt 383, 61 [46 d.C.] <span class=\"greek\">ὄρος</span> designa «deserto»; Dio Chrys. 19 [36], 40: Zoroastro retira-se dentre os homens e vive <span class=\"greek\">ἐν</span> <span class=\"greek\">ὄρει</span>; Herm. Wr. 13, inscrição: Hermes ensina seu filho Tat <span class=\"greek\">ἐν</span> <span class=\"greek\">ὄρει</span>), as montanhas desempenham papel importante nos evangelhos e nos apocalipses: Jesus prega e cura no «monte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:1</a> (HCarré, JBL 42, 1923, 39–48; Appian, Mithrid. 77 §334, entende <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span> em referência ao Olimpo da Bitínia, mas sem nomeá-lo.—Sobre o Sermão do Monte, ver GHeinrici, Beiträge II 1899; III 1905; JMüller, D. Bergpredigt 1906; KProost, De Bergrede 1914; HWeinel, D. Bergpr. 1920; KBornhäuser, D. Bergpr. 1923, 2 1927; PFiebig, Jesu Bergpr. 1924; GKittel, D. Bergpr. u. d. Ethik d. Judentums: ZST 2, 1925, 555–94; ASteinmann, D. Bergpr. 1926; AAhlberg, Bergpredikans etik 1930; MMeinertz, Z. Ethik d. Bergpr.: JMausbach Festschr. ’31, 21–32; HHuber, D. Bergpredigt ’32; RSeeberg, Z. Ethik der Bergpr. ’34; JSchneider, D. Sinn d. Bergpr. ’36; ALindsay, The Moral Teaching of Jesus ’37; MDibelius, The Sermon on the Mount ’40; TSoiron, D. Bergpr. Jesu ’41; DAndrews, The Sermon on the Mount ’42; HPreisker, D. Ethos des Urchristentums 2 ’49; HWindisch, The Mng. of the Sermon on the Mount [trad. Gilmour] ’51; WManson, Jesus the Messiah ’52, 77–93; TManson, The Sayings of Jesus ’54; GBornkamm, Jesus v. Naz. ’56, 92–100, 201–4 [trad. ingl. de JRobinson e outros ’60, 100–109, 221–25]; JJeremias, Die Bergpredigt ’59; JDupont, Les Béatitudes, I, ed. rev. ’58; II, ’69; W Davies, The Setting of the Sermon on the Mount, ’64; JManek, NovT 9, ’67, 124–31; HDBetz, The Sermon on the Mt [Hermeneia] ’95.—Sobre o local do Sermão, CKopp, The Holy Places of the Gosp., ’63, 204–13); 8:1; 15:29; chama os doze, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:13</a>; realiza milagres extraordinários, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:3</a>; ora, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:12</a>; 9:28; ApcPt 2:4. Num <span class=\"greek\">ὄρος</span> <span class=\"greek\">ὑψηλόν</span> («monte alto», Lucian, Charon 2), ele é transfigurado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:2</a>, e tentado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:8</a>; o Cristo ressuscitado apresenta-se num monte (cf. Herm. Wr. 13, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:16</a>. Jesus é levado pelo Espírito Santo <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">Θαβώρ</span>, ao grande monte Tabor, GHb 20, 61 (cf. Iren. 1, 14, 6 [Harv. I 139, 8: especulação gnóstica]); semelhantemente, o autor de Rv, <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ὄρος</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὑψηλόν</span>, sobre monte grande e alto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:10</a>. Do cume de um monte, o anjo do arrependimento mostra a Hermas outros doze montes, Hs 9, 1, 4; 7ff. Sobre o uso de montes na linguagem apocalíptica, ver também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:8</a>; 17:9 (<span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ὄρ</span>., «sete montes», como En 24:2. Cf. JohJeremias, D. Gottesberg 1919; RFrieling, D. hl. Berg im A u. NT 1930). GJs 22:3 <span class=\"greek\">ὄρ</span>. <span class=\"greek\">θεοῦ</span>, «monte de Deus», seguido por <span class=\"greek\">ἐδιχάσθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρ</span>., «o monte se partiu», e <span class=\"greek\">ἦν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρ</span>. <span class=\"greek\">ἐκεῖνο</span> <span class=\"greek\">διαφαῖνον</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">φῶς</span>, «aquele monte irradiava luz para ela». Sobre teofanias e o motivo do monte, ver JReeves, Heralds of That Good Realm ’96, 148f.—Acerca do monte ao qual Abraão levou seu filho para ali sacrificá-lo, 1 Cl 10:7 (cf. Gen 22:2; Demetr.: 722 Fgm. 7 Jac.). Especialmente acerca do Sinai (mais de uma dúzia de localizações já foram propostas): <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span> <span class=\"greek\">Σινά</span>, monte Sinai (LXX.—<span class=\"greek\">τὸ</span> <span class=\"greek\">Σιναῖον</span> <span class=\"greek\">ὄρ</span>., Jos., Ant. 2, 283f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:30</a>, 38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:24f</a>; 11:3 (cf. Is 16:1); 14:2 (cf. Ex 31:18); 15:1; também sem mencionar o nome: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5</a> (Ex 25:40); 12:20 (cf. Ex 19:13); 1 Cl 53:2; 4:7. Sobre o monte Sião (<span class=\"greek\">Σιών</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:1</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐλαιῶν</span>, o monte das Oliveiras (ver <span class=\"greek\">ἐλαία</span> 1; aproximadamente 17 metros mais alto que Jerusalém), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:1</a>; 26:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:37</a>; 22:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:1</a> e outros. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">καλούμενον</span> <span class=\"greek\">Ἐλαιῶν</span>, o monte denominado das Oliveiras, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:29</a>; 21:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:12</a> (ver <span class=\"greek\">ἐλαιών</span>). Sobre o monte Gerizim, com aproximadamente 868 metros de altitude (sem mencionar o nome), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:20f</a> (cf. Jos., Ant. 12, 10; 13, 74).—<span class=\"greek\">πόλις</span> <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">ὄρους</span> <span class=\"greek\">κειμένη</span>, cidade situada sobre elevação ou colina, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:14</a> (cf. Jos., Ant. 13, 203 <span class=\"greek\">πόλις</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ὄρους</span> <span class=\"greek\">κειμένη</span>). Também <span class=\"greek\">πόλις</span> <span class=\"greek\">οἰκοδομημένη</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἄκρον</span> <span class=\"greek\">ὄρους</span> <span class=\"greek\">ὑψηλοῦ</span>, cidade edificada no alto de um monte elevado, Ox 1 anverso, 17 (GTh 32) (Stephan. Byz. s.v. <span class=\"greek\">Ἀστέριον</span> diz que a cidade recebeu esse nome <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑψηλοῦ</span> <span class=\"greek\">ὄρους</span> <span class=\"greek\">κειμένη</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πόρρωθεν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἀστὴρ</span> <span class=\"greek\">φαίνεται</span>, «porque, situada num monte alto, parece uma estrela para quem a vê de longe»). —Plural <span class=\"greek\">τὰ</span> <span class=\"greek\">ὄρη</span>, colinas, montes, região de colinas ou montanhosa (às vezes o singular também significa região montanhosa [Diod S 20, 58, 2: um <span class=\"greek\">ὄρος</span> <span class=\"greek\">ὑψηλὸν</span> que se estende por 200 estádios, aproximadamente 40 km; Polyaenus 4, 2, 4 e outros: singular = região montanhosa; Tob 5:6 S]), AcPl Ha 5, 18; como local de pastagem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:12</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:32</a>. Como lugar remoto (ver acima; também Dio Chrys. 4, 4), com <span class=\"greek\">ἐρημίαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:38</a>. Como local de sepulturas (cf. POxy 274, 27 [I d.C.]; PRyl 153, 5; PGrenf II, 77, 22: o coveiro deve levar o cadáver <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span>, para sepultamento), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:5</a>. Devido ao isolamento, refúgio ideal para fugitivos (Appian, Bell. Civ. 4, 30 §130 <span class=\"greek\">ἐς</span> <span class=\"greek\">ὄρος</span> <span class=\"greek\">ἔφυγεν</span> = «fugiu para a região montanhosa»; 1 Macc 9:40): <span class=\"greek\">φεύγειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὄρ</span>., fugir para os montes (Plut., Mor. 869b <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄνθρωποι</span> <span class=\"greek\">καταφυγόντες</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὄρη</span> <span class=\"greek\">διεσώθησαν</span>; Jos., Bell. 1, 36, Ant. 14, 418), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:21</a>.—Proverbialmente <span class=\"greek\">ὄρη</span> <span class=\"greek\">μεθιστάνειν</span>, remover montanhas, isto é, fazer algo que parece impossível, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:2</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:20</a>; 21:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:23</a>. De Deus: <span class=\"greek\">μεθιστάνει</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">οὐρανοὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὄρη</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">βουνοὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">θαλάσσας</span>, (Deus) desloca de seus lugares os céus, os montes, as colinas e os mares, Hv 1, 3, 4 (cf. Is 54:10 e uma combinação semelhante em PGM 13, 874 <span class=\"greek\">αἱ</span> <span class=\"greek\">πέτραι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὄρη</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">θάλασσα</span> <span class=\"greek\">κτλ</span>.).—B. 23. DELG. M-M. TW. Spicq. Sv.</p></section></article>"};
